const pad = n => String(n).padStart(2, '0');
const iso = d => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const today = () => iso(new Date());
const pdate = s => new Date(s + 'T00:00:00');
const daysUntil = s => (s ? Math.round((pdate(s) - pdate(today())) / 864e5) : null);
const daysBetween = (a, b) => Math.round((pdate(b) - pdate(a)) / 864e5) + 1;
const addMonths = (s, m) => {
  const base = s && s >= today() ? s : today();
  const d = pdate(base), day = d.getDate();
  d.setMonth(d.getMonth() + Number(m));
  if (d.getDate() < day) d.setDate(0);
  return iso(d);
};
