const DICT = { en: {}, ar: {} };
function defineI18n(raw) {
  raw.split('\n').forEach(line => {
    if (!line.trim()) return;
    const p = line.split('|');
    DICT.en[p[0].trim()] = p[1].trim();
    DICT.ar[p[0].trim()] = (p[2] || p[1]).trim();
  });
}
function t(key, vars) {
  let s = DICT[LANG][key];
  if (s === undefined) s = DICT.en[key] ?? key;
  if (vars) for (const k in vars) s = s.split('{' + k + '}').join(vars[k]);
  return s;
}

