function fillPerms(p) { const s = seedPerms(), o = {}; ROLES.forEach(r => { o[r] = Object.assign({}, s[r], (p || {})[r]); }); return o; }
function fixDB(d) {
  d.perms = fillPerms(d.perms); d.rates = Object.assign({ order: 8, km: 1.15, vat: 15 }, d.rates || {});
  d.limits = d.limits || defaults().limits; d.grants = d.grants || [];
  if (!d.users.some(u => u.role === 'finance_manager')) { d.users.push(seedUsers()[5]); d.seq.usr = Math.max(d.seq.usr || 0, 6); }
  return d;
}
const DBKEY = 'or5_db';
function loadDB() {
  try { const r = localStorage.getItem(DBKEY); if (r) return fixDB(Object.assign(defaults(), JSON.parse(r))); } catch (e) {}
  return defaults();
}
