/* the role's level, raised by any active temporary permission */
const lvl = p => { const td = today(); return (DB.grants || []).filter(g => g.user_id === user().id && g.page === p && g.starts <= td && td <= g.ends).reduce((m, g) => (RANK[g.level] > RANK[m] ? g.level : m), (DB.perms[user().role] || {})[p] || 'none'); };
const canView = p => lvl(p) !== 'none';
const canEdit = p => RANK[lvl(p)] >= 2;
