/* ---------- domain helpers ---------- */
const initials = n => { const w = String(n || '?').trim().split(/\s+/); return (w[0][0] + (w[1] ? w[1][0] : '')).toUpperCase(); };
const hue = s => { let h = 0; for (const c of String(s)) h = (h * 31 + c.charCodeAt(0)) % 360; return h; };
const avatarStyle = s => { const h = hue(s); return `background:linear-gradient(135deg,hsl(${h} 78% 58%),hsl(${(h + 48) % 360} 76% 46%))`; };
const avatar = (n, cls = '') => `<span class="avatar ${cls}" style="${avatarStyle(n)}">${esc(initials(n))}</span>`;

const DOC_KINDS = { iqama: 'iqamaExpiry', ajeer: 'ajeerExpiry', driver: 'driverExpiry' };
const VDOC_KINDS = { registration: 'registrationExpiry', inspection: 'inspectionExpiry', opcard: 'opCardExpiry' };
function leaveUsed(e) {
  return DB.requests.filter(r => r.type === 'leave' && r.empId === e.id && r.status === 'approved' && r.leaveKind === 'annual').reduce((s, r) => s + Number(r.days || 0), 0);
}
const leaveBalance = e => Math.max(0, Number(e.annual ?? 21) - leaveUsed(e));

function collectAlerts() {
  const out = [];
  const push = (page, who, docKey, date, ref) => { const d = daysUntil(date); if (d !== null && d <= 60) out.push({ page, who, doc: docKey, date, days: d, ref }); };
  DB.employees.forEach(e => {
    push('people', e.name, 'doc.iqama', e.iqamaExpiry, e.id);
    if (e.ajeerExpiry) push('people', e.name, 'doc.ajeer', e.ajeerExpiry, e.id);
    if (e.driverExpiry) push('people', e.name, 'doc.driver', e.driverExpiry, e.id);
  });
  DB.vehicles.forEach(v => {
    const nm = `${v.type || t('veh.vehicle')} · ${v.plate || v.id}`;
    push('fleet', nm, 'doc.registration', v.registrationExpiry, v.id);
    push('fleet', nm, 'doc.inspection', v.inspectionExpiry, v.id);
    if (v.opCardExpiry) push('fleet', nm, 'doc.opcard', v.opCardExpiry, v.id);
  });
  DB.licenses.forEach(l => push('licenses', l.name, 'doc.license', l.expiry, l.id));
  return out.sort((a, b) => a.days - b.days);
}
function stats() {
  const emps = DB.employees, vehs = DB.vehicles;
  const couriers = emps.filter(e => e.dept === 'operations').length;
  const ready = vehs.filter(v => v.status === 'ready').length;
  const dates = [];
  emps.forEach(e => { dates.push(e.iqamaExpiry); if (e.ajeerExpiry) dates.push(e.ajeerExpiry); if (e.driverExpiry) dates.push(e.driverExpiry); });
  vehs.forEach(v => { dates.push(v.registrationExpiry, v.inspectionExpiry); if (v.opCardExpiry) dates.push(v.opCardExpiry); });
  DB.licenses.forEach(l => dates.push(l.expiry));
  const tracked = dates.filter(Boolean);
  const healthy = tracked.filter(d => daysUntil(d) > 30).length;
  const soon = tracked.filter(d => { const n = daysUntil(d); return n >= 0 && n <= 30; }).length;
  const expired = tracked.filter(d => daysUntil(d) < 0).length;
  const rows = OPS()?.rows || [];
  const totalOrders = rows.reduce((s, r) => s + r.orders, 0);
  const ach = rows.length && DB.target ? clamp(totalOrders / (DB.target * rows.length), 0, 9.99) : null;
  return {
    emps: emps.length, couriers, vehs: vehs.length, ready,
    readyPct: vehs.length ? ready / vehs.length : null,
    compPct: tracked.length ? healthy / tracked.length : null,
    tracked: tracked.length, healthy, soon, expired, totalOrders, ach,
    pending: DB.requests.filter(r => r.status === 'pending').length,
    openTasks: DB.requests.filter(r => r.type === 'task' && r.status === 'in_progress').length,
    doneTasks: DB.requests.filter(r => r.type === 'task' && r.status === 'done' && !r.seen).length,
    alerts: collectAlerts().filter(a => a.days <= 30).length,
    openMaint: DB.maint.filter(m => ['open', 'purchased'].includes(m.status)).length,
    maintReq: DB.maint.filter(m => m.status === 'requested').length,
    notices: typeof noticeList === 'function' ? noticeList().length : 0
  };
}

