/* ---------- toast ---------- */
function toast(msg, tone = 'ok') {
  const root = $('#toasts'); if (!root) return;
  const el = document.createElement('div');
  el.className = 'toast ' + tone;
  el.innerHTML = `${ic(tone === 'ok' ? 'circle-check' : tone === 'warn' ? 'alert' : 'alert')}<span>${esc(msg)}</span>`;
  root.appendChild(el);
  while (root.children.length > 3) root.firstChild.remove();
  setTimeout(() => { el.classList.add('out'); setTimeout(() => el.remove(), 420); }, 3600);
}

/* ---------- forms ---------- */
const isLetter = c => /\p{L}/u.test(c), isDigit = c => /[0-9]/.test(c);
function splitPlate(p) { const ch = [...String(p || '').replace(/\s/g, '')]; return { l: ch.filter(isLetter).slice(0, 3), n: ch.filter(isDigit).slice(0, 4) }; }
function plateHTML(p) { const s = splitPlate(p); const c = (a, k) => Array.from({ length: k }, (_, i) => `<b>${esc(a[i] || '·')}</b>`).join(''); return `<span class="plate7" dir="ltr">${c(s.l, 3)}<i></i>${c(s.n, 4)}</span>`; }
function formHTML(fields) {
  return `<div class="fg">${fields.map(f => {
    if (f.section) return `<div class="fsec" ${f.for ? `data-for="${f.for.join(',')}"` : ''}>${f.icon ? `<span class="orb ${f.tone || 't-cy'}">${ic(f.icon)}</span>` : ''}<div><b>${esc(f.section)}</b>${f.desc ? `<small>${esc(f.desc)}</small>` : ''}</div></div>`;
    const v = f.value ?? '';
    const lab = `<label for="f-${f.id}">${esc(f.label)}${f.req ? '<i>*</i>' : ''}</label>`;
    let inp;
    if (f.type === 'files') inp = `<div class="filepick" id="f-${f.id}"><button type="button" class="btn sm" data-act="fpPick" data-id="${f.id}">${ic('paperclip')}${esc(t('file.choose'))}</button><span class="hint">${esc(f.hint || t('file.hint', { n: fileMaxMB() }))}</span><input type="file" multiple hidden accept="${FILE_ACCEPT}" data-fp="${f.id}"><div class="fplist" id="fl-${f.id}"></div></div>`;
    else if (f.type === 'plate') { const sp = splitPlate(v); const cell = (k, i) => `<input class="pc ${k}" maxlength="1" autocomplete="off" autocapitalize="characters" value="${esc((sp[k][i]) || '')}" aria-label="${k === 'l' ? t('veh.plateLetters') : t('veh.plateDigits')} ${i + 1}">`; inp = `<div class="platebox" id="f-${f.id}" dir="ltr">${[0, 1, 2].map(i => cell('l', i)).join('')}<i class="pdiv"></i>${[0, 1, 2, 3].map(i => cell('n', i)).join('')}</div>`; }
    else if (f.type === 'select') inp = `<select class="in" id="f-${f.id}">${f.opts.map(([val, lb]) => `<option value="${esc(val)}" ${String(val) === String(v) ? 'selected' : ''}>${esc(lb)}</option>`).join('')}</select>`;
    else if (f.type === 'textarea') inp = `<textarea class="in" id="f-${f.id}" ${f.max ? `maxlength="${f.max}" data-count="${f.max}"` : ''} placeholder="${esc(f.ph || '')}">${esc(v)}</textarea>`;
    else inp = `<input class="in" id="f-${f.id}" type="${f.type || 'text'}" value="${esc(v)}" placeholder="${esc(f.ph || '')}" ${f.max ? `maxlength="${f.max}" data-count="${f.max}"` : ''} ${f.min !== undefined ? `min="${f.min}"` : ''} autocomplete="off">`;
    const extra = f.type === 'files' ? '' : f.max ? `<div class="count" id="c-${f.id}">${String(v).length} / ${f.max}</div>` : f.hint ? `<div class="hint">${esc(f.hint)}</div>` : '';
    return `<div class="fld ${f.wide ? 'wide' : ''}" ${f.for ? `data-for="${f.for.join(',')}"` : ''}>${lab}${inp}${extra}</div>`;
  }).join('')}</div>`;
}
function readForm(fields) {
  const vals = {}; let ok = true;
  fields.forEach(f => {
    if (f.section) return;
    const el = $('#f-' + f.id); if (!el) return;
    const row = el.closest('[data-for]');
    if (row && row.hidden) { vals[f.id] = f.type === 'files' ? [] : ''; return; }
    if (f.type === 'files') {
      const items = (FILEBOX[f.id] || []).map(file => ({ file, kind: f.kind || 'attach' }));
      vals[f.id] = items; el.classList.remove('err'); if (f.req && !items.length) { el.classList.add('err'); ok = false; }
      return;
    }
    if (f.type === 'plate') {
      const l = $$('.pc.l', el).map(i => i.value.trim()), n = $$('.pc.n', el).map(i => i.value.trim());
      const full = l.every(Boolean) && n.every(Boolean);
      vals[f.id] = full ? l.join('') + ' ' + n.join('') : '';
      el.classList.remove('err'); if (f.req && !full) { el.classList.add('err'); ok = false; }
      return;
    }
    const v = el.value.trim();
    vals[f.id] = v;
    el.classList.remove('err');
    if (f.req && !v) { el.classList.add('err'); ok = false; }
  });
  return ok ? vals : null;
}

