  if (canEdit('fleet')) A.push(['truck', 'cmd.addVeh', () => A_.addVeh()], ['wrench', 'cmd.newMaint', () => A_.newMaint()]);
  if (canEdit('licenses')) A.push(['shield', 'cmd.addLic', () => A_.addLic()]);
  if (canView('approvals') || canView('portal')) A.push(['send', 'cmd.newReq', () => A_.newReq()]);
  A.push([THEME === 'dark' ? 'sun' : 'moon', 'cmd.theme', () => A_.theme()], ['globe', 'cmd.lang', () => A_.lang()]);
  A.forEach(([i, k, run]) => items.push({ g: t('cmd.actions'), icon: i, label: t(k), kw: DICT.en[k] + ' ' + DICT.ar[k], run }));
