/* ================= REMAINING CUSTODY / PARTS FUNDS ================= */
const FUND_TYPES = ['custody_maint', 'parts'];
function fundReqs(m) { return linkedReqs(m).filter(r => FUND_TYPES.includes(r.type) && r.status === 'approved'); }
function fundIssued(m) { return fundReqs(m).reduce((s, r) => s + Number(r.amount || 0), 0); }
function fundHolder(m) {
  const r = fundReqs(m).filter(z => z.empId || z.holderName).pop();
  if (r) { const e = r.empId ? emp(r.empId) : null; return { empId: r.empId || '', name: e ? e.name : (r.holderName || '') }; }
  const u = m.assignedTo ? DB.users.find(z => z.id === m.assignedTo) : null;
  if (u) { const e = u.empId ? emp(u.empId) : null; return { empId: u.empId || '', userId: u.id, name: e ? e.name : userName(u) }; }
  return { empId: '', name: m.assignedName || '' };
}
function calcSettle(m, spent) {
  const issued = fundIssued(m), diff = Math.round((issued - spent) * 100) / 100;
  if (!issued || !diff) return null;
  const h = fundHolder(m);
  return { issued, spent, amount: Math.abs(diff), dir: diff > 0 ? 'return' : 'reimburse', empId: h.empId, userId: h.userId || '', holder: h.name, status: 'due', at: today() };
}
const dueSettles = () => DB.maint.filter(m => m.settle && m.settle.status === 'due');
const openSettles = () => DB.maint.filter(m => m.settle && ['due', 'sent'].includes(m.settle.status));
const heldBy = (e, u) => openSettles().filter(m => m.settle.dir === 'return' && ((e && m.settle.empId === e.id) || (u && m.settle.userId === u.id)));
const heldTotal = () => openSettles().filter(m => m.settle.dir === 'return').reduce((s, m) => s + m.settle.amount, 0);

function settleKV(m) {
  const s = m.settle; if (!s) return '';
  const rows = [[t('cs.issued'), SAR(s.issued)], [t('cs.spent'), SAR(s.spent)], [t(s.dir === 'return' ? 'cs.left' : 'cs.over'), SAR(s.amount)], [t('cs.holder'), s.holder || '—'], [t('req.status'), t('cs.st.' + s.status)]];
  if (s.status !== 'due') rows.push([t('cs.method'), mLabel(s.method)], [t('req.date'), fmtDate(s.settledAt || s.sentAt)]);
  if (s.voucher) rows.push([t('fin.voucherNo'), s.voucher.no]);
  if (s.note) rows.push([t('req.note'), s.note]);
  return `<h4 style="margin:22px 0 2px">${esc(t('cs.title'))}</h4>` + rows.map(([k, v]) => `<div class="kv"><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('') + (s.files && s.files.length ? filesHTML(s.files) : '');
}
const settleChip = m => m.settle ? chip(`${t(m.settle.dir === 'return' ? 'cs.left' : 'cs.over')}: ${SAR(m.settle.amount)}`, m.settle.status === 'settled' ? 'ok' : 'warn') : '';

