/* ================= HUNGERSTATION DATA, RATES & ENTITLEMENT ================= */
const HS_COLS = [
  ['name', /name|courier|rider|driver|employee|agent|اسم|مندوب|سائق|موظف/i],
  ['empNo', /(courier|rider|employee|driver|staff)?\s*(id|no\.?|number)\b|رقم|معرف|كود/i],
  ['cancel', /cancel|reject|إلغاء|الغاء|ملغ|مرفوض/i],
  ['late', /late|delay|تأخر|متأخر/i],
  ['accept', /accept|قبول/i],
  ['rating', /rating|rate\b|score|stars?|تقييم|التقييم|تقيم/i],
  ['prod', /productiv|utili[sz]ation|per\s*hour|إنتاجي|انتاجي|إنتاجية|انتاجية/i],
  ['shifts', /shift|شفت|شفتات|وردي|ورديات|دوام/i],
  ['hours', /hours?|ساعات|ساعة|duration/i],
  ['km', /distance|\bkm\b|kilomet|مسافة|المسافة|كيلو|كم\b/i],
  ['notes', /note|remark|comment|feedback|ملاحظ|تعليق|ملحوظ/i],
  ['orders', /order|deliver|complet|count|total|طلب|طرد|توصيل|عدد|اجمال|إجمال/i]
];
const HS_NUM = ['orders', 'km', 'shifts', 'hours', 'rating', 'accept', 'cancel', 'late', 'prod'];
const hsNum = v => { const n = Number(String(v ?? '').replace(/[,%\s]/g, '').replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d))); return isNaN(n) || v === '' || v == null ? null : n; };
const normName = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();

function matrixToOps(m) {
  const isNum = v => hsNum(v) !== null;
  let hi = m.findIndex(r => r.filter(c => c !== '' && c != null).length >= 2 && r.some(c => c !== '' && c != null && !isNum(c)));
  if (hi < 0) return [];
  const head = m[hi].map(x => String(x ?? '').trim()), data = m.slice(hi + 1);
  const col = {}, used = new Set();
  HS_COLS.forEach(([k, re]) => { const i = head.findIndex((h, j) => !used.has(j) && h && re.test(h)); if (i >= 0) { col[k] = i; used.add(i); } });
  if (col.name === undefined) { col.name = 0; used.add(0); }
  if (col.orders === undefined) {
    const w = Math.max(...m.map(r => r.length));
    for (let c = w - 1; c >= 0; c--) if (!used.has(c) && data.some(r => isNum(r[c]))) { col.orders = c; break; }
  }
  if (col.orders === undefined) return [];
  const map = new Map();
  data.forEach(r => {
    const name = String(r[col.name] ?? '').trim(); if (!name) return;
    const o = hsNum(r[col.orders]); if (o === null) return;
    const row = { name }; if (col.empNo !== undefined) row.empNo = String(r[col.empNo] ?? '').trim();
    HS_NUM.forEach(k => { if (col[k] !== undefined) { const v = hsNum(r[col[k]]); if (v !== null) row[k] = v; } });
    if (col.notes !== undefined && String(r[col.notes] ?? '').trim()) row.notes = String(r[col.notes]).trim();
    const key = normName(row.empNo || name), prev = map.get(key);
    if (!prev) { row._n = 1; map.set(key, row); return; }
    HS_NUM.forEach(k => { if (row[k] === undefined) return; if (['rating', 'accept', 'prod'].includes(k)) prev[k] = ((prev[k] ?? row[k]) * prev._n + row[k]) / (prev._n + 1); else prev[k] = (prev[k] || 0) + row[k]; });
    prev._n++; if (row.notes) prev.notes = [prev.notes, row.notes].filter(Boolean).join(' · ');
  });
  const out = [...map.values()].map(r => {
    delete r._n;
    const e = DB.employees.find(z => (r.empNo && z.id === r.empNo) || normName(z.name) === normName(r.name)); if (e) r.empId = e.id;
    return r;
  }).sort((a, b) => b.orders - a.orders);
  out.cols = Object.keys(col);
  return out;
}
async function handleOpsFile(file) {
  if (!file) return;
  try {
    let matrix;
    if (/\.(xlsx|xls)$/i.test(file.name)) {
      const X = await loadXLSX(); const wb = X.read(await file.arrayBuffer(), XLSX_OPTS);
      matrix = X.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { header: 1, defval: '' });
    } else matrix = parseCSV(await file.text());
    const rows = matrixToOps(matrix);
    if (!rows.length) { toast(t('ops.parseFail'), 'warn'); return; }
    DB.ops = { file: file.name, at: today(), rows, cols: rows.cols }; save(); toast(t('ops.loaded', { n: rows.length })); render();
  } catch (e) { toast(t('ops.readFail'), 'bad'); }
}
