/* ---------- money ---------- */
const SEGS = ['A', 'B', 'C', 'D', 'F'];
const RATE_DEF = { order: 8, km: 1.15, vat: 15, segA: 2.75, segB: 2.25, segC: 1.75, segD: 1.25, segF: 0 };
const rates = () => Object.assign({}, RATE_DEF, DB.rates || {});
/* quality bonus for the company, per completed order, by the courier's HungerStation segment */
const segRate = s => (SEGS.includes(s) ? Number(rates()['seg' + s]) || 0 : 0);
const r2 = n => Math.round(n * 100) / 100;
function entOf(r) {
  const k = rates(), o = r2((r.orders || 0) * k.order), d = r2((r.km || 0) * k.km), b = r2((r.orders || 0) * segRate(r.segment)), sub = r2(o + d + b), vat = r2(sub * k.vat / 100);
  return { orders: o, km: d, bonus: b, sub, vat, total: r2(sub + vat) };
}
const entTotals = () => (OPS()?.rows || []).reduce((a, r) => { const e = entOf(r); ['orders', 'km', 'bonus', 'sub', 'vat', 'total'].forEach(k => a[k] = r2(a[k] + e[k])); return a; }, { orders: 0, km: 0, bonus: 0, sub: 0, vat: 0, total: 0 });
/* the entitlement from HungerStation is for the CEO only */
const MONEY_ROLES = ['ceo', 'finance_manager', 'accountant', 'cashier'];
const seesEntitlement = () => MONEY_ROLES.includes(user().role);
const money = n => nf(r2(n)).replace(/(\.\d)$/, '$10');
const fmtRating = v => (v === undefined ? '—' : v > 5 ? `${Math.round(v * 10) / 10}%` : (Math.round(v * 100) / 100).toFixed(2));
const ratingTone = v => (v === undefined ? 'info' : v > 5 ? (v >= 90 ? 'ok' : v >= 75 ? 'warn' : 'bad') : (v >= 4.5 ? 'ok' : v >= 4 ? 'warn' : 'bad'));
const hsRowOf = e => { const o = OPS(); return e && o ? o.rows.find(r => r.empId === e.id || (!r.rider && normName(r.name) === normName(e.name))) : null; };
const hsProd = r => (r.prod !== undefined ? r.prod : r.hours ? r.orders / r.hours : r.shifts ? r.orders / r.shifts : undefined);
const hsProdLabel = r => (r.prod !== undefined || r.hours ? t('hs.perHour') : t('hs.perShift'));

