/* ================= HungerStation daily reports, kept as history =================
   Each upload adds its days to the record; uploading a day again replaces only that day.
   The operations page adds everything up over the chosen date range. */
const HS = { key: '', data: null, busy: false, rev: 0, view: null, vkey: '' };
const HS_LOCAL = 'oceanrise.hs';
const hsLocal = () => { try { return JSON.parse(localStorage.getItem(HS_LOCAL) || '[]'); } catch (e) { return []; } };
const HS_ALIAS = { riderid: 'rider_id', rider_number: 'rider_id', rider_no: 'rider_id', rider_code: 'rider_id' };
const hsKeyOf = h => { const k = String(h ?? '').replace(/^\uFEFF/, '').trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, ''); return HS_ALIAS[k] || k; };
const HS_MON = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };
