  if (typeof v === 'number' && v > 40000 && v < 80000) { const d = new Date(Date.UTC(1899, 11, 30) + Math.floor(v) * 864e5); return mk(d.getUTCFullYear(), d.getUTCMonth() + 1, d.getUTCDate()); }
