  const n = String(name || '').replace(/\.[a-z0-9]+$/i, ''); let m;
  if ((m = n.match(/(20\d\d)[-_.](\d{1,2})[-_.](\d{1,2})/))) return hsDate(`${m[1]}-${m[2]}-${m[3]}`);
  if ((m = n.match(/(\d{1,2})[-_.](\d{1,2})[-_.](20\d\d)/))) return hsDate(`${m[1]}/${m[2]}/${m[3]}`);
  if ((m = n.match(/([A-Za-z]{3})[A-Za-z]*[\s_-]+(\d{1,2})[\s_,-]+(20\d\d)/))) return hsDate(`${m[1]} ${m[2]}, ${m[3]}`);
  if ((m = n.match(/(\d{1,2})[\s_-]+([A-Za-z]{3})[A-Za-z]*[\s_-]+(20\d\d)/))) return hsDate(`${m[1]} ${m[2]} ${m[3]}`);
