  const riders = [...R.values()].map(r => { if (r._days.size) r.days = r._days.size; return strip(r); })
    .sort((a, c) => (c.completed ?? c.km_orders ?? 0) - (a.completed ?? a.km_orders ?? 0) || (a.rider < c.rider ? -1 : 1));
  const days = [...D.values()].map(d => { d.riders = d._r.size; return strip(d); }).sort((a, c) => (a.d < c.d ? 1 : -1));
