  const tabs = [['payments', t('fin.tab.payments'), nDue], ['settlements', t('fin.tab.settlements'), nSet], ['vouchers', t('fin.tab.vouchers')], ...(ent ? [['entitlement', t('fin.tab.entitlement')]] : [])];
