  const who = [[t('req.from'), r.from], [t('print.empNo'), e ? e.id : '—'], [t('emp.job'), e ? e.job : '—'], [t('emp.dept'), e && e.dept ? t('dept.' + e.dept) : '—']];
  const info = [[t('req.id'), r.id], [t('req.type'), t('rtype.' + r.type)], [t('req.date'), fmtDate(r.date)], [t('req.status'), t('st.' + r.status)]];
  const det = [];
  if (r.type === 'leave') det.push([t('lk.label'), t('lk.' + r.leaveKind)], [t('req.days'), t('req.daysN', { n: r.days })], [t('req.from_d'), fmtDate(r.fromDate)], [t('req.to_d'), fmtDate(r.to)], ...(e ? [[t('leave.balance'), t('req.daysN', { n: leaveBalance(e) })]] : []));
  if (r.type === 'balance') det.push([t('req.days'), `+${t('req.daysN', { n: r.days })}`], ...(e ? [[t('leave.balance'), t('req.daysN', { n: leaveBalance(e) })]] : []));
  if (r.amount && r.type !== 'leave') det.push([t('req.amount'), SAR(r.amount)]);
  if (m) det.push([t('req.maint'), `${maintLabel(m)} — ${m.issue}`]);
  if (r.vendor) det.push([t('req.vendor'), r.vendor]);
  if (r.holderName) det.push([t('req.holder'), r.holderName]);
  if (r.type === 'task') det.push([t('task.assignee'), r.assignee]);
  if (r.assignedName) det.push([t('req.assigned'), r.assignedName]);
  const body = `<h2>${esc(t('print.reqInfo'))}</h2>${kvRows(info)}
    <h2>${esc(t('print.requester'))}</h2>${kvRows(who)}
    ${det.length ? `<h2>${esc(t('print.reqDetails'))}</h2>${kvRows(det)}` : ''}
    <h2>${esc(t('req.details'))}</h2><div class="box">${esc(r.type === 'task' ? `${r.title}\n${r.details || ''}` : r.details || '—')}</div>
    ${r.items ? `<h2>${esc(t('req.items'))}</h2><div class="box">${esc(r.items)}</div>` : ''}
    ${r.note ? `<h2>${esc(t('req.note'))}</h2><div class="box">${esc(r.note)}</div>` : ''}
    <h2>${esc(t('req.files'))}</h2>${filesList(r.files)}
    ${pathTable(r)}
    ${sigBoxes([t('print.requesterSign'), ...(r.workflow || []).map(w => t('wf.' + w.role))].slice(0, 5))}
    ${['custody', 'custody_maint'].includes(r.type) ? `<h2>${esc(t('print.custodyAck'))}</h2><div class="box">${esc(t('print.custodyText'))}</div>${sigBoxes([t('print.receiver'), t('print.issuer')])}` : ''}`;
