  const wide = head.length > 6;
  const cell = (v, i) => { let s = String(v ?? '—'); if (/^\d{4}-\d{2}-\d{2}$/.test(s)) s = fmtDate(s); return esc(s.length > 90 ? s.slice(0, 88) + '…' : s); };
