  const types = ['leave', 'advance', 'balance', 'custody', 'parts', 'custody_maint', 'expense', 'iqama_renew', 'license_renew', 'hire_courier', 'notice', 'general', 'task'];
  const reqRows = types.map(ty => { const a = DB.requests.filter(r => r.type === ty); return a.length ? `<tr><td>${esc(t('rtype.' + ty))}</td><td>${a.length}</td><td>${cnt(a, r => r.status === 'pending')}</td><td>${cnt(a, r => r.status === 'approved' || r.status === 'done')}</td><td>${cnt(a, r => r.status === 'rejected')}</td><td>${a.reduce((x, r) => x + Number(r.amount || 0), 0) ? esc(SAR(a.reduce((x, r) => x + Number(r.amount || 0), 0))) : '—'}</td></tr>` : ''; }).join('');
  const mCost = DB.maint.reduce((x, m) => x + Number(m.cost || 0), 0);
