/* ---------- change password ---------- */
function pwModal(locked) {
  openModal({
    title: t('auth.changePw'), desc: locked ? t('auth.must') : t('auth.pwHint'), locked: !!locked, size: 'sm',
    fields: [{ id: 'old', label: t('auth.old'), type: 'password', req: true, wide: true }, { id: 'nw', label: t('auth.new'), type: 'password', req: true, wide: true, hint: t('auth.pwHint') }, { id: 'nw2', label: t('auth.new2'), type: 'password', req: true, wide: true }],
    submit: t('act.save'), noCancel: !!locked,
    onSubmit: v => {
      if (v.nw !== v.nw2) return t('auth.mismatch');
      if (v.nw.length < 8 || !/[A-Za-z]/.test(v.nw) || !/[0-9]/.test(v.nw)) return t('auth.weak');
      (async () => {
        const r = await fn('change-password', { oldPassword: v.old, newPassword: v.nw });
        if (!r.ok) { toast(r.status === 429 ? t('auth.locked', { s: 15 }) : t(r.data.error === 'wrongOld' ? 'auth.wrongOld' : r.data.error === 'same' ? 'auth.same' : r.data.error === 'leaked' ? 'auth.leaked' : 'auth.weak'), 'warn'); return; }
        closeModal(); toast(t('auth.pwDone'));
        if (SRV.me && SRV.me.must) { SRV.me.must = false; try { adopt(await fetchAll()); UI.page = firstPage(); render(true); } catch (e) { toast(t('sync.fail'), 'bad'); } }
      })();
      return false;
    }
  });
}
A_.changePw = () => pwModal(false);

