/* ================= main: shell · render · events ================= */
ICONS.globe = '<circle cx="12" cy="12" r="10"/><path d="M2 12h20M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/>';
const MAIN_NAV = ['overview', 'people', 'fleet', 'ops', 'licenses', 'approvals', 'finance', 'reports', 'alerts', 'portal'];
const SYS_NAV = ['users', 'settings'];

function applyShell() {
  const root = document.documentElement;
  root.lang = LANG; root.dir = LANG === 'ar' ? 'rtl' : 'ltr'; root.setAttribute('data-theme', THEME);
  document.title = `oceanrise · ${t('app.title')}`;
  $('#brandLogo').innerHTML = `<img alt="oceanrise" src="${LOGO_SRC}">`;
  $('#navLabelMain').textContent = t('nav.main'); $('#navLabelSys').textContent = t('nav.system');
  $('#cmdText').textContent = t('cmd.search'); $('#crumbSmall').textContent = t('crumb.small');
  $('#crumbTitle').textContent = t('page.' + UI.page);
  $('#langSeg').dataset.v = LANG === 'ar' ? '1' : '0';
  $$('#langSeg button').forEach(b => b.classList.toggle('on', b.dataset.v === LANG));
  $('#themeBtn').innerHTML = ic(THEME === 'dark' ? 'sun' : 'moon');
  $('#menuBtn').innerHTML = ic('menu'); $('#minibtn').innerHTML = ic('collapse', 'flip'); $('#bell').innerHTML = ic('bell') + '<em class="dot" hidden></em>';
  $('#cmdIcon').innerHTML = ic('search');
  const meta = $('meta[name="theme-color"]'); if (meta) meta.content = THEME === 'dark' ? '#030b16' : '#e8f1f8';
  const s = stats();
  const mkNav = list => list.filter(canView).map(p => {
    const n = p === 'approvals' ? s.pending : p === 'alerts' ? s.alerts + s.notices : p === 'fleet' && canEdit('fleet') ? s.maintReq : p === 'finance' ? finBadge() : 0;
    return `<button class="${UI.page === p ? 'on' : ''}" data-act="go" data-p="${p}" title="${esc(t('page.' + p))}">${ic(PAGE_ICON[p])}<span class="lbl">${esc(t('page.' + p))}</span>${n ? `<span class="badge">${n}</span>` : ''}</button>`;
  }).join('');
  const nav = $('#nav'); $$('button', nav).forEach(b => b.remove()); nav.insertAdjacentHTML('beforeend', mkNav(MAIN_NAV));
  const sys = $('#sysNav'); $$('button', sys).forEach(b => b.remove()); sys.insertAdjacentHTML('beforeend', mkNav(SYS_NAV));
  $('#sysWrap').hidden = !SYS_NAV.some(canView);
  const bell = $('#bell .dot'), bn = s.alerts + s.notices; if (bn) { bell.hidden = false; bell.textContent = bn > 9 ? '9+' : bn; }
  const u = user();
  $('#uAvatar').innerHTML = avatar(userName(u));
  $('#userSel').innerHTML = DB.users.filter(x => x.status === 'active').map(x => `<option value="${x.id}" ${x.id === u.id ? 'selected' : ''}>${esc(userName(x))}</option>`).join('');
  $('#userSel').title = t('usr.switch');
  if (SRV.on) { $('#uName').textContent = userName(u); $('#uName').title = u.username || ''; $('#pwBtn').innerHTML = ic('key'); $('#pwBtn').title = t('auth.changePw'); $('#outBtn').innerHTML = ic('logout'); $('#outBtn').title = t('auth.logout'); }
  requestAnimationFrame(movePill);
}
function movePill() {
  $$('.nav .pill').forEach(p => (p.style.opacity = 0));
  const b = $('.nav button.on'); if (!b) return;
  const p = b.parentElement.querySelector('.pill'); p.style.height = b.offsetHeight + 'px'; p.style.transform = `translateY(${b.offsetTop}px)`; p.style.opacity = 1;
}
/* actions that need more than edit access (permissions document) */
const GATE = { editRates: () => user().role === 'ceo', hsClearDay: () => canFull('ops'), hsLink: () => canEdit('people'), resetEmpPw: () => canFull('people'), addEmp: () => canFull('people'), delEmp: () => canFull('people'), adjBalance: () => canFull('people'), delVeh: () => canFull('fleet'), delLic: () => canFull('licenses'), maintAccept: () => canApprove('fleet'), maintDecline: () => canApprove('fleet') };
function gateActs(root) { for (const a in GATE) if (!GATE[a]()) $$(`[data-act="${a}"]`, root).forEach(b => b.remove()); }
for (const a in GATE) { const f = A_[a]; if (f) A_[a] = d => (GATE[a]() ? f(d) : toast(t('err.noaccess'), 'warn')); }
function render(animate) {
  if (!canView(UI.page)) UI.page = firstPage();
  const act = document.activeElement; const keep = act && act.dataset && act.dataset.search ? { id: act.id, s: act.selectionStart } : null;
  applyShell();
  const v = $('#view');
  v.innerHTML = VIEWS[UI.page]();
  gateActs(v);
  if (animate) { v.classList.remove('enter'); void v.offsetWidth; v.classList.add('enter'); clearTimeout(render.t); render.t = setTimeout(() => v.classList.remove('enter'), 1500); }
  countUp();
  if (keep) { const el = $('#' + keep.id); if (el) { el.focus(); try { el.setSelectionRange(keep.s, keep.s); } catch (e) {} } }
}
function go(p) {
  if (!canView(p)) { toast(t('err.noaccess'), 'warn'); return; }
  UI.page = p; $('#rail').classList.remove('open'); render(true); window.scrollTo({ top: 0 });
}
function countUp() {
  $$('#view :is(div,span)[data-count]').forEach(el => {
    const target = Number(el.dataset.count); if (!isFinite(target) || target <= 0) return;
    const t0 = performance.now(), dur = 1300;
    const step = now => { const k = Math.min(1, (now - t0) / dur), e = 1 - Math.pow(1 - k, 4); el.textContent = nf(Math.round(target * e)); if (k < 1) requestAnimationFrame(step); };
    requestAnimationFrame(step);
  });
}

/* ---------- events ---------- */
A_.tab = d => { UI.tab[d.page] = d.tab; render(true); };
A_.closeModal = () => { if (!MODAL || !MODAL.locked) closeModal(); };
A_.cmdk = () => openCmdk();
A_.bell = () => go('alerts');
A_.openRail = () => $('#rail').classList.add('open');
A_.mini = () => { $('#rail').classList.toggle('mini'); setPref('mini', $('#rail').classList.contains('mini') ? '1' : '0'); setTimeout(movePill, 480); setTimeout(movePill, 60); };
document.addEventListener('click', e => {
  const c = e.target.closest('[data-cmd]'); if (c) { runCmd(Number(c.dataset.cmd)); return; }
  if (e.target.id === 'cback') { closeCmdk(); return; }
  const el = e.target.closest('[data-act]');
  if (el && A_[el.dataset.act]) { e.preventDefault(); A_[el.dataset.act](el.dataset, e); }
});
document.addEventListener('change', e => {
  const el = e.target; if (!el.dataset || !el.dataset.drange) return;
  const pg = el.dataset.drange; UI.dr[pg] = { ...(UI.dr[pg] || {}), [el.dataset.k]: el.value }; render();
});
document.addEventListener('input', e => {
  const el = e.target;
  if (el.dataset && el.dataset.search) { UI.q[el.dataset.search] = el.value; render(); return; }
  if ((el.tagName === 'INPUT' || el.tagName === 'TEXTAREA') && el.dataset.count) {
    const c = $('#c-' + el.id.replace('f-', '')); if (c) { const m = Number(el.dataset.count); c.textContent = `${el.value.length} / ${m}`; c.classList.toggle('hot', el.value.length > m * .85); }
  }
});
const plateCells = el => $$('.pc', el.closest('.platebox'));
document.addEventListener('input', e => {
  const el = e.target; if (!el.classList || !el.classList.contains('pc')) return;
  const L = el.classList.contains('l');
  let v = L ? el.value.replace(/[^\p{L}]/gu, '') : el.value.replace(/[^0-9]/g, '');
  el.value = v.slice(-1).toUpperCase();
  if (el.value) { const c = plateCells(el); const nx = c[c.indexOf(el) + 1]; if (nx) nx.focus(); }
}, true);
document.addEventListener('keydown', e => {
  const el = e.target; if (!el.classList || !el.classList.contains('pc')) return;
  const c = plateCells(el), i = c.indexOf(el);
  if (e.key === 'Backspace' && !el.value && c[i - 1]) { c[i - 1].focus(); c[i - 1].value = ''; e.preventDefault(); }
  else if (e.key === 'ArrowLeft' && c[i - 1]) { c[i - 1].focus(); e.preventDefault(); }
  else if (e.key === 'ArrowRight' && c[i + 1]) { c[i + 1].focus(); e.preventDefault(); }
});
document.addEventListener('paste', e => {
  const el = e.target; if (!el.classList || !el.classList.contains('pc')) return;
  e.preventDefault(); const sp = splitPlate((e.clipboardData || window.clipboardData).getData('text'));
  const c = plateCells(el); const L = c.filter(x => x.classList.contains('l')), N = c.filter(x => x.classList.contains('n'));
  L.forEach((x, i) => (x.value = (sp.l[i] || '').toUpperCase())); N.forEach((x, i) => (x.value = sp.n[i] || ''));
  (N[Math.min(sp.n.length, 3)] || N[3]).focus();
});
document.addEventListener('change', e => {
  const el = e.target;
  if (el.dataset && el.dataset.fp) { addFiles(el.dataset.fp, [...el.files]); el.value = ''; return; }
  if (el.id === 'userSel') { CUR = el.value; setPref('user', CUR); if (!canView(UI.page)) UI.page = firstPage(); render(true); return; }
  if (el.id === 'opsfile') { handleOpsFiles(el.files); el.value = ''; return; }
  if (el.id === 'jsonfile') {
    const f = el.files[0]; if (!f) return; const r = new FileReader();
    r.onload = () => { try { const o = JSON.parse(r.result); if (!Array.isArray(o.employees)) throw 0; DB = Object.assign(defaults(), o); save(); toast(t('set.imported')); render(true); } catch (x) { toast(t('set.badFile'), 'bad'); } };
    r.readAsText(f); el.value = ''; return;
  }
  const k = el.dataset && el.dataset.change; if (!k) return;
  if (k === 'urole') { const u = DB.users.find(x => x.id === el.dataset.id); u.role = el.value; }
  if (k === 'ulink') { const u = DB.users.find(x => x.id === el.dataset.id); u.empId = el.value; }
  if (k === 'perm') { (DB.perms[el.dataset.role] = DB.perms[el.dataset.role] || {})[el.dataset.page] = el.value; }
  if (k === 'limit') { DB.limits = DB.limits || {}; if (el.value === '') delete DB.limits[el.dataset.role]; else DB.limits[el.dataset.role] = Math.max(0, Number(el.value) || 0); }
  save(); toast(t('toast.saved')); render();
});
document.addEventListener('keydown', e => {
  if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); $('#cmdRoot').innerHTML ? closeCmdk() : openCmdk(); return; }
  if (e.key === 'Escape') { if ($('#cmdRoot').innerHTML) closeCmdk(); else if (MODAL && !MODAL.locked) closeModal(); else $('#rail').classList.remove('open'); }
});
document.addEventListener('pointermove', e => {
  const s = e.target.closest && e.target.closest('.spot'); if (!s) return;
  const r = s.getBoundingClientRect(); s.style.setProperty('--mx', (e.clientX - r.left) + 'px'); s.style.setProperty('--my', (e.clientY - r.top) + 'px');
});
['dragover', 'dragleave', 'drop'].forEach(ev => document.addEventListener(ev, e => {
  const fp = e.target.closest && e.target.closest('.filepick');
  if (fp) { e.preventDefault(); fp.classList.toggle('over', ev === 'dragover'); if (ev === 'drop') addFiles(fp.id.replace('f-', ''), [...e.dataTransfer.files]); return; }
  const z = e.target.closest && e.target.closest('#dropzone'); if (!z) return;
  e.preventDefault();
  if (ev === 'dragover') z.classList.add('over'); else z.classList.remove('over');
  if (ev === 'drop' && e.dataTransfer.files.length) handleOpsFiles(e.dataTransfer.files);
}));
window.addEventListener('resize', () => requestAnimationFrame(movePill));
setInterval(() => { const c = $('#clock'); if (c) c.textContent = clockText(); }, 30000);

/* ---------- boot ---------- */
(async function boot() {
  if (pref('mini', '0') === '1') $('#rail').classList.add('mini');
  document.body.classList.add('ready');
  if (await bootServer()) return;
  if (!canView(UI.page)) UI.page = firstPage();
  render(true);
})();

A_.closeRail=()=>document.getElementById('rail').classList.remove('open');
